script.lang:
-- ️ Insert possible values for Donor Funding Administrative Level (if not already existing) INSERT INTO util_global_settings_possible_ (setting_name, value_id, value_shown) SELECT 'Donor Funding Administrative Level', 'Administrative Level 0', 'Administrative Level 0' WHERE NOT EXISTS ( SELECT 1 FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level' AND value_id = 'Administrative Level 0' AND value_shown = 'Administrative Level 0' ) UNION SELECT 'Donor Funding Administrative Level', 'Administrative Level 1', 'Administrative Level 1' WHERE NOT EXISTS ( SELECT 1 FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level' AND value_id = 'Administrative Level 1' AND value_shown = 'Administrative Level 1' ) UNION SELECT 'Donor Funding Administrative Level', 'Administrative Level 2', 'Administrative Level 2' WHERE NOT EXISTS ( SELECT 1 FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level' AND value_id = 'Administrative Level 2' AND value_shown = 'Administrative Level 2' ) UNION SELECT 'Donor Funding Administrative Level', 'Administrative Level 3', 'Administrative Level 3' WHERE NOT EXISTS ( SELECT 1 FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level' AND value_id = 'Administrative Level 3' AND value_shown = 'Administrative Level 3' ) UNION SELECT 'Donor Funding Administrative Level', 'Administrative Level 4', 'Administrative Level 4' WHERE NOT EXISTS ( SELECT 1 FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level' AND value_id = 'Administrative Level 4' AND value_shown = 'Administrative Level 4' );
-- Create or replace view for dropdown (value_id kept as varchar) CREATE OR REPLACE VIEW v_g_donor_funding_settings_admin_levels AS SELECT value_id AS id, value_shown AS value FROM util_global_settings_possible_ WHERE setting_name = 'Donor Funding Administrative Level';
-- Insert into amp_global_settings if not already existing INSERT INTO amp_global_settings (id, settingsname, settingsvalue, possiblevalues, description, section, value_translatable) SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM amp_global_settings), 'Donor Funding Administrative Level', 'Administrative Level 0', 'v_g_donor_funding_settings_admin_levels', 'Specifies which administrative level applies when doing donor funding imports', 'general', TRUE WHERE NOT EXISTS ( SELECT 1 FROM amp_global_settings WHERE settingsname = 'Donor Funding Administrative Level' );
